#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

cd "$(dirname "${BASH_SOURCE[0]}")/.."   # the project root, wherever the wizard is started from

TOTAL_STAGES=9
CONFIG_FILE="outreach.toml"

# toml_set KEY VALUE: set a top-level string setting in outreach.toml (before any [table]).
toml_set() {
  python3 - "$CONFIG_FILE" "$1" "$2" <<'PY'
import json, re, sys
path, key, value = sys.argv[1:4]
lines = open(path).read().splitlines()
new = f"{key} = {json.dumps(value)}"
for i, line in enumerate(lines):
    if re.match(rf"^{re.escape(key)}\s*=", line):
        lines[i] = new
        break
else:
    at = next((i for i, l in enumerate(lines) if l.startswith("[")), len(lines))
    lines.insert(at, new)
open(path, "w").write("\n".join(lines) + "\n")
PY
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$1" "$CONFIG_FILE"
}

banner "Jobright Outreach Agent: sign-ins and setup"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Check the tools on this Mac"
MISSING=0
for tool in uv python3 claude open; do
  if command -v "$tool" >/dev/null 2>&1; then say "✓ $tool"; else warn "missing: $tool"; MISSING=1; fi
done
if (( MISSING )); then
  warn "Install what's missing (uv: https://docs.astral.sh/uv/, claude: Claude Code), then re-run."
  exit 1
fi
say "Syncing the project's Python environment..."
uv sync >/dev/null && say "✓ uv sync"
pause "All good. Press Enter for Google Cloud."

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Google Cloud: create a project (free, no card needed)"
open_url "https://console.cloud.google.com/projectcreate"
step "Sign in with the Gmail account you send from."
step "Project name: jobright-outreach. Leave Organization/Location as they are."
step "Click Create. If Google asks for a billing account or card, skip it: the Gmail API doesn't need one."
step "Wait for the notification, then make sure the new project is selected in the top bar."
pause "Project created and selected? Press Enter."

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Google Cloud: turn on the Gmail API"
open_url "https://console.cloud.google.com/apis/library/gmail.googleapis.com"
step "Check the top bar still shows jobright-outreach."
step "Click Enable."
pause "It says 'API enabled' (or shows a Manage button)? Press Enter."

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Google Cloud: set up the consent screen"
open_url "https://console.cloud.google.com/auth/overview"
step "If you see 'Get started': App name = Jobright Outreach, User support email = your Gmail. Next."
step "Audience: External. Next."
step "Contact email: your Gmail. Next. Tick the policy box, then Continue and Create."
step "Left menu → Audience: under 'Test users' click Add users and add YOUR Gmail address. Save."
step "Left menu → Data Access → Add or remove scopes: search 'Gmail API', tick  .../auth/gmail.modify  → Update → Save."
note "Google's console layout changes now and then. If a label differs, look for the same idea. Leave the app in 'Testing': no review needed."
note "While it is in Testing, the Gmail sign-in expires every 7 days. Re-run stage 7 (or 'uv run outreach gmail-auth') when that happens."
note "To end that later, run scripts/gmail-production-wizard.sh."
pause "Test user added and the gmail.modify scope saved? Press Enter."

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Google Cloud: create the OAuth client and save credentials.json"
open_url "https://console.cloud.google.com/auth/clients/create"
step "Application type: Desktop app. Name: Jobright Outreach CLI. Click Create."
step "In the dialog click 'Download JSON'. It lands in your Downloads folder as client_secret_....json."
GUESS=$(ls -t "$HOME"/Downloads/client_secret*.json 2>/dev/null | head -n1 || true)
[[ -n "$GUESS" ]] && note "Found: $GUESS"
ask CLIENT_JSON "Path to the downloaded JSON (Enter for the one above, or drag the file here):"
CLIENT_JSON="${CLIENT_JSON:-$GUESS}"
CLIENT_JSON="${CLIENT_JSON//\\ / }"; CLIENT_JSON="${CLIENT_JSON%\'}"; CLIENT_JSON="${CLIENT_JSON#\'}"; CLIENT_JSON="${CLIENT_JSON/#\~/$HOME}"
if [[ ! -f "$CLIENT_JSON" ]]; then warn "No file at: $CLIENT_JSON. Re-run the wizard."; exit 1; fi
if ! python3 -c 'import json,sys; assert "installed" in json.load(open(sys.argv[1]))' "$CLIENT_JSON" 2>/dev/null; then
  warn "That file isn't a Desktop-app client (no \"installed\" section). Create the client again with type 'Desktop app'."; exit 1
fi
cp "$CLIENT_JSON" credentials.json && chmod 600 credentials.json
say "✓ saved credentials.json (gitignored, mode 600)"
if confirm "Delete the downloaded copy in Downloads?"; then rm -f "$CLIENT_JSON" && say "✓ deleted"; fi
pause "Press Enter to write the config."

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Write outreach.toml"
[[ -f "$CONFIG_FILE" ]] || { cp outreach.example.toml "$CONFIG_FILE"; say "✓ created $CONFIG_FILE from the example"; }
ask SENDER_ADDR "Your Gmail address (the sender):"
[[ "$SENDER_ADDR" == *@*.* && "$SENDER_ADDR" != *+* ]] || { warn "That doesn't look like a plain address. Re-run."; exit 1; }
say "For the live test, emails go to plus-addresses of your own inbox (you+outreachtest7@...)."
ask TEST_ADDR "Test inbox (Enter for the same address):"
TEST_ADDR="${TEST_ADDR:-$SENDER_ADDR}"
[[ "$TEST_ADDR" == *@*.* && "$TEST_ADDR" != *+* ]] || { warn "Use a plain address with no '+'. Re-run."; exit 1; }
DEFAULT_RESUMES="$PWD/resumes"   # the five resume PDFs live in the project (gitignored)
ask RESUME_DIR "Resume folder (Enter for $DEFAULT_RESUMES):"
RESUME_DIR="${RESUME_DIR:-$DEFAULT_RESUMES}"; RESUME_DIR="${RESUME_DIR/#\~/$HOME}"
toml_set sender "$SENDER_ADDR"
toml_set test_recipient "$TEST_ADDR"
toml_set resume_dir "$RESUME_DIR"
toml_set humanizer_check ".claude/skills/outreach-humanizer/check.py"
warn "test_recipient is ON. Set it to \"\" in outreach.toml before any real outreach."
pause "Press Enter for the Gmail sign-in."

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Sign in to Gmail from the project"
say "A browser tab opens next. In it:"
step "Pick the same Gmail account."
step "'Google hasn't verified this app': click Advanced → 'Go to Jobright Outreach (unsafe)'. This is your own app in Testing mode, so that's expected."
step "Allow the Gmail permission (read, compose, send), then close the tab when it says you can."
pause "Press Enter to start the sign-in."
uv run outreach gmail-auth
[[ -f data/gmail_token.json ]] && say "✓ token saved to data/gmail_token.json" || { warn "No token was saved. Re-run this wizard."; exit 1; }
pause "Check that the address printed above is the one you meant. Enter to continue."

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Check the config and resume files"
uv run outreach config | grep -E '"(sender|test_recipient|resume_dir|humanizer_check)"'
BAD=0
for f in Forward_Deployed ML AI Data Software; do
  p="$RESUME_DIR/Kusai_Hajuri_Resume_${f}_Engineer.pdf"
  if [[ -f "$p" ]]; then say "✓ $(basename "$p")"; else warn "missing: $p"; BAD=1; fi
done
[[ -f ".claude/skills/outreach-humanizer/check.py" ]] && say "✓ outreach-humanizer check.py" || { warn "the project's outreach-humanizer check.py is missing"; BAD=1; }
(( BAD )) && warn "Fix the missing files above, or edit outreach.toml. You can continue and fix them later."
pause "Press Enter for the browser sign-ins."

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Browser sign-ins that Claude relies on"
open_url "https://jobright.ai/jobs/applied"
step "Jobright: you must be signed in to your Premium account, and the Applied list must load. Check it shows today's applications."
open_url "https://claude.ai/settings/connectors"
step "Claude: the Gmail connector must be connected (a read-only bounce check uses it). Connect it if it isn't."
step "Chrome: the 'Claude in Chrome' extension must be installed, enabled and signed in to the same Claude account."
pause "All three are working? Press Enter."

finish
say "Next: run the live test with its own data folder:"
say "  uv run outreach start --contacts 2 --data-dir data/live-test --db data/live-test.db"
printf '\n'
}

run_wizard "$@"; exit
